import java.util.*

val MOD = 998244353

data class Matrix(val size: Int, val data: Array<LongArray>) {
    operator fun times(other: Matrix): Matrix {
        val res = Array(size) { LongArray(size) }
        for (i in 0 until size) {
            for (k in 0 until size) {
                if (data[i][k] == 0L) continue
                for (j in 0 until size) {
                    res[i][j] = (res[i][j] + data[i][k] * other.data[k][j]) % MOD
                }
            }
        }
        return Matrix(size, res)
    }
}

fun matrixPower(mat: Matrix, power: Long): Matrix {
    var result = Matrix(mat.size, Array(mat.size) { LongArray(mat.size) })
    for (i in 0 until mat.size) result.data[i][i] = 1
    var base = mat
    var exp = power
    while (exp > 0) {
        if (exp % 2 == 1L) {
            result = result * base
        }
        base = base * base
        exp /= 2
    }
    return result
}

fun main() {
    val sc = Scanner(System.`in`)
    val n = sc.nextInt()
    val m = sc.nextLong()
    val words = Array(n) { sc.next() }

    val maxLen = words.maxOf { it.length }
    val size = maxLen

    val transitions = Array(size) { LongArray(size) }
    for (i in 0 until size) {
        for (word in words) {
            val len = word.length
            if (len == i + 1) {
                transitions[i][0] = (transitions[i][0] + 1) % MOD
            }
        }
    }

    for (i in 0 until size) {
        for (j in 0 until size) {
            if (i + 1 + j < size) {
                transitions[i + 1 + j][j] = (transitions[i + 1 + j][j] + transitions[i][j]) % MOD
            }
        }
    }

    val mat = Matrix(size, transitions)
    val matPower = matrixPower(mat, m)

    var total = 0L
    for (i in 0 until size) {
        total = (total + matPower.data[0][i]) % MOD
    }

    val same = Array(size) { LongArray(size) }
    for (i in 0 until size) {
        same[i][i] = 1
    }
    val sameMat = Matrix(size, same)
    val samePower = matrixPower(sameMat, m)

    var sameCount = 0L
    for (i in 0 until size) {
        sameCount = (sameCount + samePower.data[0][i]) % MOD
    }

    val ans = (total * total % MOD - sameCount + MOD) % MOD
    println(ans)
}
```

